pub fn get(
    kinds_arg: &str,
    name: Option<&str>,
    namespace_flag: Option<&str>,
    all_namespaces: bool,
    selector: Option<&str>,
    format_spec: Option<&str>,
) -> Outcome {
    let kinds = resolve_kinds(kinds_arg)?;
    let format = parse_format(format_spec)?;

