            return Err(Failure::Usage(format!(
                "kubelike: {} is not a namespaced resource",
                kind.plural
            )));
        }
    }

    let namespace = config::resolve_namespace(namespace_flag);

    let mut selected: Vec<(&'static KindMeta, Vec<Resource>)> = Vec::new();

