            for (_, field) in columns {
                if !kind.fields.contains(&field.as_str()) {
                    return Err(Failure::Domain(format!(
                        "kubelike: unknown field \"{}\" for {}; valid fields: {}",
                        field,
                        kind.plural,
                        kind.fields.join(", ")
                    )));
                }
            }
        }
    }

    match &format {
        Format::Json => {
            if name.is_some() {
